after.content:
    }
}

private static Optional<String> optionalText(Object value) {
    return value == null || String.valueOf(value).isBlank()
            ? Optional.empty() : Optional.of(String.valueOf(value));
}

private static Optional<byte[]> optionalBytes(Object value) {
    return value == null || String.valueOf(value).isBlank()
            ? Optional.empty() : Optional.of(decode(value));
}

private static byte[] decode(Object value) {
    return Base64.getDecoder().decode(String.valueOf(value));
}
